vault = "2d71502f699aaef5b075e99d72875df0906334ea259091b9cf1a220e1558d87a520b285c25d4"

# Build block dict
ct2pt = {}
for ct_hex, pt in pairs:
    ct = bytes.fromhex(ct_hex)
    for i in range(0, len(ct), 16):
        block = ct[i:i+16]
        pt_chunk = pt[i:i+16].encode()
        if len(block) == 16:
