    if block in ct2pt:
        result += ct2pt[block]
        print(f"Block {i//16}: MATCH ({len(ct2pt[block])}b) -> {ct2pt[block]}")
    else:
        print(f"Block {i//16}: UNKNOWN {block.hex()} ({len(block)} bytes)")
