# Display
try:
    text = result.decode('ascii', errors='replace')
    print(f"\nDecrypted: '{text}'")
    if 'FLAG' in text:
        import re
        for f in re.findall(r'FLAG\{[^}]+\}', text):
            print(f"FLAG: {f}")
except:
    print(f"Raw: {result}")
